import sys

def solve():
    n = int(sys.stdin.readline())
    a = sys.stdin.readline().strip()
    b = sys.stdin.readline().strip()

    if len(a) != len(b):
        print(-1)
        return

    if a == b:
        print(0)
        return

    diff = [int(b[i]) - int(a[i]) for i in range(n)]
    moves = []

    for i in range(n - 1):
        if diff[i] != 0:
            if diff[i] == diff[i + 1]:
                moves.append((i + 1, diff[i]))
                diff[i] = 0
                diff[i + 1] = 0
            else:
                if abs(diff[i]) > 1 or abs(diff[i + 1]) > 1:
                    print(-1)
                    return
                if diff[i] == 1 and diff[i + 1] == -1:
                    moves.append((i + 1, 1))
                    moves.append((i + 1, -1))
                    diff[i] = 0
                    diff[i + 1] = 0
                elif diff[i] == -1 and diff[i + 1] == 1:
                    moves.append((i + 1, -1))
                    moves.append((i + 1, 1))
                    diff[i] = 0
                    diff[i + 1] = 0
                else:
                    print(-1)
                    return

    if any(d != 0 for d in diff):
        print(-1)
        return

    print(len(moves))
    for move in moves[:10**5]:
        print(move[0], move[1])

solve()
